        with self.lock:
            existed = self._live(key) is not None
            self.data[key] = (value, None if ttl is None else time.monotonic() + ttl)
            return existed

    def get(self, key):
        with self.lock:
            return self._live(key)

    def delete(self, key):
        with self.lock:
            if self._live(key) is None:
                return False
            del self.data[key]
