    def _send(self, status, body=None):
        if status == 204:
            self.send_response(204)
            self.end_headers()
            return
        raw = json.dumps(body).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def _key(self):
        path = self.path.split("?", 1)[0]
        if path.startswith("/kv/"):
            key = path[4:]
            if key and "/" not in key:
                return key
        return None

    def _route(self, method):
        path = self.path.split("?", 1)[0]
        if path == "/kv":
            if method == "GET":
                return self._send(200, {"keys": self.server.store.keys()})
            return self._send(405, {"error": "method not allowed"})
        key = self._key()
        if key is None:
            return self._send(404, {"error": "not found"})
        store = self.server.store
        if method == "GET":
            item = store.get(key)
            if item is None:
                return self._send(404, {"error": "not found"})
            return self._send(200, {"key": key, "value": item[0]})
        if method == "DELETE":
            if store.delete(key):
                return self._send(204)
            return self._send(404, {"error": "not found"})
        if method == "PUT":
            try:
                length = int(self.headers.get("Content-Length") or 0)
            except ValueError:
                length = 0
            raw = self.rfile.read(length) if length > 0 else b""
            try:
                body = json.loads(raw.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                return self._send(400, {"error": "invalid JSON"})
            if not isinstance(body, dict):
                return self._send(400, {"error": "body must be a JSON object"})
            if "value" not in body:
                return self._send(400, {"error": "missing value"})
            ttl = body.get("ttl")
            if "ttl" in body:
                if (isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                        or not math.isfinite(ttl) or ttl <= 0):
                    return self._send(400, {"error": "ttl must be a number greater than 0"})
            else:
                ttl = None
            existed = store.put(key, body["value"], ttl)
            return self._send(200 if existed else 201, {"key": key, "value": body["value"]})
        self._send(405, {"error": "method not allowed"})

    def do_GET(self):
        self._route("GET")

    def do_PUT(self):
        self._route("PUT")

    def do_DELETE(self):
        self._route("DELETE")

    def do_POST(self):
        self._send(404 if self._key() is None and self.path.split("?")[0] != "/kv" else 405,
                   {"error": "method not allowed"})

    do_PATCH = do_POST


def make_server(host, port):
    server = ThreadingHTTPServer((host, port), Handler)
    server.daemon_threads = True
    server.store = Store()
    return server


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--port", type=int, required=True)
    p.add_argument("--host", default="127.0.0.1")
    a = p.parse_args()
    make_server(a.host, a.port).serve_forever()


if __name__ == "__main__":
    main()
